+        button.addEventListener("click", () => {
+          const index = Number(button.dataset.index);
+          state.openIndex = state.openIndex === index ? null : index;
+          render();
+        });
+      });
+    }
+
+    render();
+  </script>
+</body>
+</html>
*** End Patch
