  <title>Cat FAQ</title>
  <style>
    :root {
      color-scheme: light;
      --bg: #f5f7fb;
      --panel: rgba(255, 255, 255, 0.88);
      --panel-border: rgba(15, 23, 42, 0.08);
      --text: #0f172a;
      --muted: #475569;
      --accent: #7c3aed;
      --accent-soft: rgba(124, 58, 237, 0.12);
      --shadow: 0 20px 50px rgba(15, 23, 42, 0.12);
      --radius: 24px;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(124, 58, 237, 0.16), transparent 30%),
        radial-gradient(circle at top right, rgba(59, 130, 246, 0.14), transparent 28%),
        linear-gradient(180deg, #ffffff 0%, var(--bg) 100%);
    }

    .page-shell {
      width: min(960px, calc(100% - 32px));
      margin: 0 auto;
      padding: 56px 0 72px;
    }

    .hero {
      display: grid;
      gap: 18px;
      padding: 32px;
      border: 1px solid var(--panel-border);
      border-radius: calc(var(--radius) + 4px);
      background: var(--panel);
      backdrop-filter: blur(16px);
      box-shadow: var(--shadow);
    }

    .eyebrow {
      width: fit-content;
      padding: 8px 12px;
      border-radius: 999px;
      background: var(--accent-soft);
      color: var(--accent);
      font-size: 0.8rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2.2rem, 4vw, 4rem);
      line-height: 1;
      letter-spacing: -0.04em;
    }

    .hero p {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
      font-size: 1.05rem;
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 18px;
      margin-top: 28px;
    }

    .example {
      border: 1px solid rgba(148, 163, 184, 0.2);
      border-radius: var(--radius);
      background: rgba(255, 255, 255, 0.82);
      box-shadow: 0 12px 32px rgba(15, 23, 42, 0.08);
      overflow: clip;
    }

    .question-toggle {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      width: 100%;
      padding: 22px 24px;
      border: 0;
      background: transparent;
      color: inherit;
      font: inherit;
      text-align: left;
      cursor: pointer;
    }

    .question-copy {
      display: grid;
      gap: 8px;
    }

    .question-index {
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    .question-title {
      font-size: 1.08rem;
      font-weight: 700;
      line-height: 1.4;
    }

    .chevron {
      flex: 0 0 auto;
      width: 42px;
      height: 42px;
      display: grid;
      place-items: center;
      border-radius: 50%;
      background: rgba(15, 23, 42, 0.04);
      color: var(--accent);
      transition: transform 180ms ease, background-color 180ms ease;
    }

    .example.is-open .chevron {
      transform: rotate(180deg);
      background: var(--accent-soft);
    }

    .details {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 220ms ease;
    }

    .example.is-open .details {
      grid-template-rows: 1fr;
    }

    .details-inner {
      min-height: 0;
      overflow: hidden;
    }

    .answer {
      padding: 0 24px 24px;
      color: var(--muted);
      line-height: 1.75;
      font-size: 0.98rem;
      border-top: 1px solid rgba(148, 163, 184, 0.18);
    }

    .answer p {
      margin: 18px 0 0;
    }

    @media (max-width: 640px) {
      .page-shell {
        width: min(100% - 20px, 960px);
        padding: 20px 0 36px;
      }

      .hero,
      .question-toggle,
      .answer {
        padding-left: 18px;
        padding-right: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    const faqs = [
      {
        question: "Why do cats sleep so much?",
        answer: "Cats are natural predators that conserve energy between bursts of activity. Even indoor cats keep that instinct, which is why long naps are completely normal."
      },
      {
        question: "Why do cats purr?",
        answer: "Purring often signals comfort and contentment, but cats may also purr when they want reassurance or feel stressed. It is one of their most flexible ways to communicate."
      },
      {
        question: "Do cats always land on their feet?",
        answer: "Cats have an impressive righting reflex, but they do not always land safely. Falls can still cause serious injury, so windows, balconies, and high ledges should be secured."
      },
      {
        question: "What does it mean when a cat kneads?",
        answer: "Kneading is a leftover kitten behavior linked to comfort and security. Adult cats often knead blankets, cushions, or people when they feel relaxed and safe."
      },
      {
        question: "How can I help a shy cat feel comfortable?",
        answer: "Give the cat quiet places to hide, let them approach at their own pace, and keep routines predictable. Patience usually works better than trying to force interaction."
      }
    ];

    const state = {
      openIndex: null
    };

    const escapeHtml = (value) =>
      value
        .replaceAll("&", "&amp;")
        .replaceAll("<", "&lt;")
        .replaceAll(">", "&gt;")
        .replaceAll('"', "&quot;")
        .replaceAll("'", "&#39;");

    function Hero() {
      return `
        <section class="hero">
          <div class="eyebrow">Cat Care FAQ</div>
          <h1>Everything curious people ask about cats.</h1>
          <p>
            A clean, product-style FAQ with simple disclosures. Every answer starts collapsed,
            and each question expands on demand for a focused reading experience.
          </p>
        </section>
      `;
    }

    function FAQItem(item, index) {
      const isOpen = state.openIndex === index;
      const contentId = `faq-answer-${index}`;

      return `
        <div class="example${isOpen ? " is-open" : ""}">
          <button
            class="question-toggle"
            type="button"
            aria-expanded="${isOpen}"
            aria-controls="${contentId}"
            data-index="${index}"
          >
            <span class="question-copy">
              <span class="question-index">Question ${index + 1}</span>
              <span class="question-title">${escapeHtml(item.question)}</span>
            </span>
            <span class="chevron" aria-hidden="true">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                <path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>
              </svg>
            </span>
          </button>
          <div class="details" id="${contentId}">
            <div class="details-inner">
              <div class="answer">
                <p>${escapeHtml(item.answer)}</p>
              </div>
            </div>
          </div>
        </div>
      `;
    }

    function FAQList(items) {
      return `
        <section class="faq-list" aria-label="Frequently asked questions">
          ${items.map((item, index) => FAQItem(item, index)).join("")}
        </section>
      `;
    }

    function App() {
      return `
        <main class="page-shell">
          ${Hero()}
          ${FAQList(faqs)}
        </main>
      `;
    }

    function render() {
      const root = document.getElementById("app");
      root.innerHTML = App();

      root.querySelectorAll(".question-toggle").forEach((button) => {
        button.addEventListener("click", () => {
          const index = Number(button.dataset.index);
          state.openIndex = state.openIndex === index ? null : index;
          render();
        });
      });
    }

    render();
  </script>
</body>
</html>
