       letter-spacing: -0.04em;
     }

     .hero p {
       margin: 0;
       max-width: 62ch;
       color: var(--muted);
       font-size: 1.05rem;
       line-height: 1.7;
     }

     .faq-list {
       display: grid;
       gap: 18px;
       margin-top: 28px;
     }

     .example {
       border: 1px solid rgba(148, 163, 184, 0.2);
