   <div id="app"></div>

   <script>
     const faqs = [
       {
         question: "Why do cats sleep so much?",
         answer: "Cats are natural predators that conserve energy between bursts of activity. Even indoor cats keep that instinct, which is why long naps are completely normal."
       },
       {
         question: "Why do cats purr?",
         answer: "Purring often signals comfort and contentment, but cats may also purr when they want reassurance or feel stressed. It is one of their most flexible ways to communicate."
       },
       {
         question: "Do cats always land on their feet?",
         answer: "Cats have an impressive righting reflex, but they do not always land safely. Falls can still cause serious injury, so windows, balconies, and high ledges should be secured."
       },
       {
         question: "What does it mean when a cat kneads?",
         answer: "Kneading is a leftover kitten behavior linked to comfort and security. Adult cats often knead blankets, cushions, or people when they feel relaxed and safe."
       },
       {
         question: "How can I help a shy cat feel comfortable?",
         answer: "Give the cat quiet places to hide, let them approach at their own pace, and keep routines predictable. Patience usually works better than trying to force interaction."
       }
     ];

     const state = {
       openIndex: null
     };

     const escapeHtml = (value) =>
       value
         .replaceAll("&", "&amp;")
         .replaceAll("<", "&lt;")
         .replaceAll(">", "&gt;")
         .replaceAll('"', "&quot;")
         .replaceAll("'", "&#39;");

     function Hero() {
       return `
         <section class="hero">
           <div class="eyebrow">Cat Care FAQ</div>
           <h1>Everything curious people ask about cats.</h1>
           <p>
             A clean, product-style FAQ with simple disclosures. Every answer starts collapsed,
             and each question expands on demand for a focused reading experience.
           </p>
         </section>
       `;
     }

     function FAQItem(item, index) {
       const isOpen = state.openIndex === index;
       const contentId = `faq-answer-${index}`;

       return `
         <div class="example${isOpen ? " is-open" : ""}">
           <button
             class="question-toggle"
             type="button"
             aria-expanded="${isOpen}"
             aria-controls="${contentId}"
             data-index="${index}"
           >
             <span class="question-copy">
               <span class="question-index">Question ${index + 1}</span>
               <span class="question-title">${escapeHtml(item.question)}</span>
             </span>
             <span class="chevron" aria-hidden="true">
               <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                 <path d="M6 9l6 6 6-6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>
               </svg>
             </span>
')
